/* ===================== BÀI 72 · Phòng thực hành SQL: SQLite chạy ngay trên trình duyệt ===================== */
/* l72 · Phòng thực hành SQL — sinh bởi tools/author/sql/lab.js, không sửa tay.
   Trình soạn SQL, hình động từng bước, bài tập chấm tự động (57-sql-*.js). Bài tập chỉ mang mã băm của kết quả đúng, không mang đáp án. */
makeSqlLab(document.getElementById("sql-l72"),{id:"sql-l72",file:"thuc-hanh.sql",presets:[{"label":"Ví dụ: câu SELECT đầu tiên","note":"SELECT * lấy mọi cột; câu thứ hai chỉ lấy hai cột của học viên đã có điểm, sắp theo điểm giảm dần (cùng điểm thì theo id). Bấm Từng bước để chạy từng câu.","data":"lop","sql":"-- Mọi cột, mọi dòng của bảng hoc_vien\nSELECT * FROM hoc_vien;\n\n-- Hai cột, chỉ học viên đã có điểm, điểm từ cao xuống thấp\nSELECT ho_ten, diem\nFROM hoc_vien\nWHERE diem IS NOT NULL\nORDER BY diem DESC, id;"},{"label":"Ví dụ: lọc, sắp xếp, lấy vài dòng đầu","note":"WHERE lọc dòng, ORDER BY sắp xếp, LIMIT lấy số dòng đầu tiên. Thứ tự viết: SELECT … FROM … WHERE … ORDER BY … LIMIT.","data":"lop","sql":"SELECT ho_ten, lop, diem\nFROM hoc_vien\nWHERE lop = '10A'\nORDER BY diem DESC\nLIMIT 2;"},{"label":"Ví dụ: thêm, sửa, xóa từng bước","note":"Bấm Từng bước: sau mỗi câu, phần Cơ sở dữ liệu tô màu bảng vừa đổi. Bấm ↺ để trở về dữ liệu mẫu.","data":"lop","sql":"INSERT INTO hoc_vien (id, ho_ten, lop, nam_sinh, diem)\nVALUES (9, 'Cao Lâm', '10C', 2010, 7);\n\nUPDATE hoc_vien SET diem = 6\nWHERE id = 4;\n\nDELETE FROM hoc_vien\nWHERE lop IS NULL;\n\nSELECT id, ho_ten, lop, diem FROM hoc_vien;"},{"label":"Ví dụ: thống kê theo lớp","note":"GROUP BY lop: mỗi lớp một dòng. COUNT(*) đếm học viên, AVG(diem) bỏ qua điểm NULL. NULLS LAST xếp nhóm NULL (chưa xếp lớp) xuống cuối; ghi rõ như vậy để SQLite và PostgreSQL xếp giống nhau. Hình động GROUP BY ở mục L.3 cho xem từng bước.","data":"lop","sql":"SELECT lop, COUNT(*) AS so_hv, ROUND(AVG(diem), 2) AS diem_tb\nFROM hoc_vien\nGROUP BY lop\nORDER BY lop NULLS LAST;"},{"label":"Ví dụ: JOIN khách hàng với đơn hàng","note":"Ghép mỗi đơn với khách đặt đơn đó qua khóa ngoại khach_id. tong_tien tính bằng nghìn đồng (giả định).","data":"cuahang","sql":"SELECT k.ten, d.id AS don, d.ngay, d.tong_tien\nFROM khach_hang AS k\nJOIN don_hang AS d ON d.khach_id = k.id\nORDER BY d.ngay;"},{"label":"Bẫy: = NULL không tìm được dòng nào","note":"So sánh với NULL bằng = luôn cho NULL (chưa biết), nên câu thứ nhất trả về 0 dòng. Câu thứ hai dùng IS NULL mới đúng.","data":"lop","sql":"SELECT ho_ten FROM hoc_vien WHERE diem = NULL;\n\nSELECT ho_ten FROM hoc_vien WHERE diem IS NULL;"},{"label":"Bẫy: quên dấu phẩy, cột biến thành bí danh","note":"Không có lỗi! SQLite hiểu “ho_ten diem” là cột ho_ten với bí danh diem, nên kết quả chỉ có MỘT cột tên diem chứa họ tên.","data":"lop","sql":"SELECT ho_ten diem\nFROM hoc_vien;"},{"label":"Bẫy: LIMIT 2, 3 chỉ có ở SQLite","note":"Hai câu cho cùng kết quả trên SQLite. Trên PostgreSQL câu thứ nhất báo lỗi cú pháp; viết LIMIT … OFFSET … để chạy được ở cả hai.","data":"lop","sql":"SELECT id, ho_ten FROM hoc_vien ORDER BY id LIMIT 2, 3;\n\nSELECT id, ho_ten FROM hoc_vien ORDER BY id LIMIT 3 OFFSET 2;"},{"label":"Lỗi: gõ sai tên cột","note":"Bảng không có cột ten (cột đúng là ho_ten). Xem thông báo lỗi tiếng Việt và dòng bị tô đỏ.","data":"lop","sql":"SELECT ten, diem\nFROM hoc_vien\nWHERE diem >= 8;"},{"label":"Lỗi: khóa ngoại chặn đơn của khách không có thật","note":"don_hang.khach_id tham chiếu khach_hang(id). Không có khách số 9 nên INSERT bị chặn; bảng không đổi.","data":"cuahang","sql":"INSERT INTO don_hang (id, khach_id, ngay, tong_tien)\nVALUES (107, 9, '2026-03-05', 150);\n\nSELECT COUNT(*) FROM don_hang;"},{"label":"Ví dụ: giao dịch và ROLLBACK","note":"Trong giao dịch, xóa hết bảng rồi ROLLBACK: dữ liệu trở lại như lúc BEGIN. Đếm số dòng trước và sau để thấy.","data":"lop","sql":"BEGIN;\nDELETE FROM hoc_vien;\nSELECT COUNT(*) AS con_lai FROM hoc_vien;\nROLLBACK;\n\nSELECT COUNT(*) AS con_lai FROM hoc_vien;"}]});
