makeSqlEx(document.getElementById("ex-l72"),"l72",[{"t":"Học viên lớp 10B đã có điểm","d":"<p>Bảng <code>hoc_vien<\/code>. Liệt kê <b>họ tên<\/b> và <b>điểm<\/b> của học viên lớp <code>10B<\/code> <b>đã có điểm<\/b>, sắp theo điểm giảm dần; cùng điểm thì theo họ tên tăng dần. Kết quả có 2 cột theo đúng thứ tự: ho_ten, diem.<\/p>","data":"lop","kt":["lop_kt"],"start":"SELECT ho_ten, diem\nFROM hoc_vien\n-- viết tiếp WHERE và ORDER BY\n","ordered":true,"checks":[{"c":2,"n":2,"h":"3db733313b469f2026c99860a5ab2f65","uh":"607d7a44661826db256e8c223cb49d06"},{"c":2,"n":2,"h":"38972388f79544afa0df953a407bdfa0","uh":"38972388f79544afa0df953a407bdfa0"}],"hints":["Hai điều kiện nối bằng AND: lớp là '10B', và điểm không phải NULL.","“Đã có điểm” viết là <code>diem IS NOT NULL<\/code>; <code>diem != NULL<\/code> không bao giờ TRUE.","Sắp theo hai cột: <code>ORDER BY diem DESC, ho_ten<\/code>."],"why":"Hai điều kiện nối bằng AND; học viên vắng thi có diem NULL nên chỉ IS NOT NULL loại được họ (bộ dữ liệu kiểm tra thêm cũng có học viên 10B chưa có điểm). Sắp theo hai cột: điểm giảm dần trước, họ tên sau."},{"t":"Sĩ số và điểm cao nhất của mỗi lớp","d":"<p>Bảng <code>hoc_vien<\/code>. Với mỗi lớp (bỏ qua học viên chưa xếp lớp), cho biết <b>tên lớp<\/b>, <b>số học viên<\/b> và <b>điểm cao nhất<\/b>. Kết quả 3 cột: lop, số học viên, điểm cao nhất; thứ tự dòng không quan trọng.<\/p>","data":"lop","kt":["lop_kt"],"start":"SELECT lop, COUNT(*), MAX(diem)\nFROM hoc_vien\n","ordered":false,"checks":[{"c":3,"n":3,"h":"e240eb79b558a4ee38a0069050e77b35"},{"c":3,"n":3,"h":"1bb4f84844acf5c241c8f3e4a6fd3a45"}],"hints":["Mỗi lớp một dòng: cần <code>GROUP BY lop<\/code>.","Học viên chưa xếp lớp (lop là NULL) tạo thành nhóm NULL riêng; loại họ bằng <code>WHERE lop IS NOT NULL<\/code> trước khi gom nhóm.","Số học viên là <code>COUNT(*)<\/code>, không phải <code>COUNT(diem)<\/code> (học viên vắng thi vẫn là học viên của lớp)."],"why":"WHERE chạy trước GROUP BY nên loại học viên chưa xếp lớp ở WHERE thì nhóm NULL không xuất hiện. COUNT(*) đếm cả học viên vắng thi; MAX bỏ qua NULL."},{"t":"Tổng tiền đã mua của từng khách, kể cả khách chưa mua","d":"<p>Hai bảng <code>khach_hang<\/code> và <code>don_hang<\/code>. Với <b>mọi<\/b> khách hàng, cho biết <b>tên<\/b> và <b>tổng tong_tien<\/b> các đơn của khách đó; khách chưa mua đơn nào ghi <b>0<\/b> (không phải NULL). Sắp theo tổng giảm dần, cùng tổng thì theo tên tăng dần. Kết quả 2 cột: ten, tổng.<\/p>","data":"cuahang","kt":["cuahang_kt"],"start":"SELECT k.ten, SUM(d.tong_tien)\nFROM khach_hang AS k\nJOIN don_hang AS d ON d.khach_id = k.id\nGROUP BY k.id, k.ten;\n","ordered":true,"checks":[{"c":2,"n":4,"h":"4881830eca669c103f4579b3706257bc","uh":"4881830eca669c103f4579b3706257bc"},{"c":2,"n":5,"h":"83e412600211a4046e74b343378712aa","uh":"4ef5a74d08597d3b4ef96c4380e63347"}],"hints":["Câu mẫu dùng JOIN (INNER) nên khách chưa mua bị mất. Đổi sang <code>LEFT JOIN<\/code>.","Với khách chưa mua, SUM của toàn NULL là NULL. <code>COALESCE(SUM(d.tong_tien), 0)<\/code> đổi NULL thành 0.","Đặt bí danh cho cột tổng rồi <code>ORDER BY tong DESC, k.ten<\/code>."],"why":"LEFT JOIN giữ khách chưa mua (ghép với NULL), COALESCE đổi tổng NULL thành 0, gom nhóm theo cả k.id để hai khách trùng tên không bị gộp làm một."}]);

makeQuiz("quiz72","score72",[{"q": "Bảng hoc_vien có một học viên vắng thi (diem là NULL). Câu SELECT * FROM hoc_vien WHERE diem = NULL trả về bao nhiêu dòng?", "o": ["1 dòng: học viên vắng thi", "Báo lỗi cú pháp", "0 dòng", "Mọi dòng của bảng"], "a": 2, "e": "So sánh với NULL bằng = cho NULL (chưa biết), không phải TRUE, nên WHERE bỏ mọi dòng. Muốn tìm ô trống thì dùng IS NULL."}, {"q": "Khách Dũng chưa mua đơn nào. Muốn danh sách khách kèm đơn hàng vẫn có Dũng, dùng phép ghép nào?", "o": ["khach_hang LEFT JOIN don_hang", "khach_hang INNER JOIN don_hang", "don_hang INNER JOIN khach_hang", "khach_hang CROSS JOIN don_hang"], "a": 0, "e": "LEFT JOIN giữ mọi dòng của bảng bên trái (khach_hang); dòng không khớp được ghép với NULL. INNER JOIN bỏ khách không có đơn; CROSS JOIN ghép mọi khách với mọi đơn."}, {"q": "Lớp 10B có 3 học viên, một người vắng thi. Với lớp 10B, COUNT(*) và COUNT(diem) lần lượt bằng bao nhiêu?", "o": ["2 và 2", "3 và 3", "2 và 3", "3 và 2"], "a": 3, "e": "COUNT(*) đếm số dòng của nhóm (3); COUNT(diem) chỉ đếm dòng có giá trị diem khác NULL (2)."}, {"q": "Câu nào chạy được và cho cùng kết quả trên cả SQLite và PostgreSQL?", "o": ["SELECT id FROM hoc_vien ORDER BY id LIMIT 2, 3", "SELECT id FROM hoc_vien ORDER BY id LIMIT 3 OFFSET 2", "SELECT IFNULL(diem, 0) FROM hoc_vien", "SELECT GROUP_CONCAT(ho_ten) FROM hoc_vien"], "a": 1, "e": "LIMIT … OFFSET … có ở cả hai hệ. LIMIT a, b, IFNULL và GROUP_CONCAT là cú pháp riêng của SQLite; PostgreSQL báo lỗi (đã chạy thử, xem bảng mục L.4)."}]);

